const cfg = window.R2V_QUALITY_CONFIG || {};
const db = window.supabase?.createClient?.(cfg.supabaseUrl, cfg.supabaseKey);
const $ = (id) => document.getElementById(id);
async function uploadStorageObject(bucket,path,blob,contentType=blob.type||'application/octet-stream'){
  const baseUrl=String(cfg.supabaseUrl||'').replace(/\/$/,''),encodedPath=path.split('/').map(encodeURIComponent).join('/');
  const response=await fetch(`${baseUrl}/storage/v1/object/${encodeURIComponent(bucket)}/${encodedPath}`,{method:'PUT',headers:{apikey:cfg.supabaseKey,Authorization:`Bearer ${cfg.supabaseKey}`,'Content-Type':contentType,'x-upsert':'true'},body:blob});
  if(!response.ok){const detail=await response.text();throw new Error(detail||`图片上传失败（HTTP ${response.status}）`);}
  return `${baseUrl}/storage/v1/object/public/${encodeURIComponent(bucket)}/${encodedPath}`;
}
