function statisticsType(c){const s=state.sopSettings,date=day(c.feedback_date||c.case_date);if(!s.enabled||!s.startDate||date<s.startDate)return '原生产';if(c.kind==='quality'&&!s.qualityEnabled)return '原生产';if(c.kind==='acceptance'&&!s.acceptanceEnabled)return '原生产';const events=state.eventsByTid.get(c.tid)||[],resultNames=c.kind==='quality'?['质检通过','质检不通过','质检打回']:['验收通过','验收不通过','验收打回'],restartNames=c.kind==='quality'?['标注']:['进入验收池','验收派单'],historical=events.some(e=>resultNames.includes(e.event_name)&&day(e.event_time)<s.startDate),restarted=events.some(e=>restartNames.includes(e.event_name)&&day(e.event_time)>=s.startDate&&day(e.event_time)<=date);return historical&&restarted?'新SOP复检':'新规正常生产';}
