function useCustomDates(){if($('startDate').value||$('endDate').value)$('periodSelect').value='custom';}
async function applyPeriod(){const start=$('startDate').value,end=$('endDate').value;if(start&&end&&start>end)return showStatus('开始日不能晚于结束日。',true);state.casePage=1;state.appealPage=1;state.loadedSignature='';await loadAll();if($('periodSelect').value!=='idle')showStatus(`已按 ${periodBounds().label} 加载。`);}

