  state.imports=imports||[];state.importById=new Map(state.imports.map(item=>[item.id,item]));state.adminAudit=audit||[];state.summaryMode=false;state.loadedSignature=`imports|${state.workstream}`;await loadSopSettingsFromCloud();renderAll();showStatus(`${workstreamLabel()}上传记录已加载。`);
