function renderDailyStats(){const a=aggregate(),rows=state.summaryMode?state.dailySnapshots.map(row=>{const p=row.payload||{};return {date:day(row.stat_date),q:Number(p.qTotal||0),errors:Number(p.qErrors||0),acc:Number(p.aTotal||0),fails:Number(p.aFail||0)}}).sort((x,y)=>y.date.localeCompare(x.date)):(()=>{const dates=new Set([...a.qRounds.map(r=>day(r.date)),...a.aRounds.map(r=>day(r.resultDate))]);return [...dates].filter(Boolean).sort().reverse().map(date=>{const q=a.qRounds.filter(r=>day(r.date)===date),keys=new Set(q.map(r=>r.key)),errors=new Set(a.qCases.filter(c=>c.final_error&&keys.has(c.round_key)).map(c=>c.round_key)),acc=a.aRounds.filter(r=>day(r.resultDate)===date),fails=acc.filter(r=>r.result==='failed').length;return {date,q:q.length,errors:errors.size,acc:acc.length,fails}})})();$('periodSummary').textContent=`当前范围：${periodBounds().label}。质检按质检结果日统计，验收按验收结果日统计，区间数据为多天累计。`;$('dailyTable').innerHTML=rows.length?rows.map(r=>`<tr><td><strong>${esc(r.date)}</strong></td><td>${r.q}</td><td>${r.errors}</td><td class="rate">${pct(r.q-r.errors,r.q)}</td><td>${r.acc}</td><td>${r.fails}</td><td class="rate">${pct(r.acc-r.fails,r.acc)}</td></tr>`).join(''):'<tr><td colspan="7" class="empty-cell">所选日期范围内暂无质检或验收数据。</td></tr>';}
