function peopleRows(rows,full=true){if(!rows.length)return `<tr><td colspan="${full?14:12}" class="empty-cell">上传流水和反馈表后，这里会自动出现人员结果。</td></tr>`;return rows.map(p=>{const profile=STAFF_PROFILES[p.name]||{},staffType=STAFF_TYPES[p.name]||'';return `<tr><td><strong>${esc(p.name)}</strong></td><td>${staffType?`<span class="staff-type">${esc(staffType)}</span>`:'—'}</td><td>${esc(staffBoss(p.name)||'—')}</td><td>${esc(staffLead(p.name)||'—')}</td><td class="staff-date">${esc(profile.hireDate||'—')}</td><td>${p.qTotal}</td><td>${p.p0}</td><td>${p.p1}</td><td>${p.p2}</td>${full?`<td>${p.errors.size}</td>`:`<td>${p.approved}</td>`}<td class="rate">${pct(p.qTotal-p.errors.size,p.qTotal)}</td>${full?`<td>${p.aTotal}</td><td>${p.aFail}</td>`:''}<td class="rate">${pct(p.aTotal-p.aFail,p.aTotal)}</td></tr>`}).join('')}
