function filteredPeople(rows){const name=String($('peopleNameFilter')?.value||'').trim().toLowerCase(),exact=[['peopleTypeFilter','type'],['peopleBossFilter','boss'],['peopleLeadFilter','lead'],['peopleHireDateFilter','hireDate'],['peopleQTotalFilter','qTotal'],['peopleP0Filter','p0'],['peopleP1Filter','p1'],['peopleP2Filter','p2'],['peopleErrorFilter','errors'],['peopleQRateFilter','qRate'],['peopleATotalFilter','aTotal'],['peopleAFailFilter','aFail'],['peopleARateFilter','aRate']];return rows.filter(p=>{const d=peopleRowData(p);return (!name||d.name.toLowerCase().includes(name))&&exact.every(([id,key])=>peopleFilterValue(id)==='all'||peopleFilterValue(id)===d[key])})}
