function qualityReturned(c){if(c.kind!=='quality')return '—';return c.needs_change===true?'是':c.needs_change===false?'否':'未填写';}
function feedbackExcelRow(c){const n=Number(c.raw_row?.excelRow);return Number.isFinite(n)&&n>0?n:Number.MAX_SAFE_INTEGER;}
function feedbackOrder(a,b){const dateDiff=String(day(b.feedback_date)).localeCompare(String(day(a.feedback_date)));if(dateDiff)return dateDiff;const ar=feedbackExcelRow(a),br=feedbackExcelRow(b);if(ar!==br)return ar-br;return String(a.tid||'').localeCompare(String(b.tid||''));}
function editableIdentityCase(c){return c?.kind==='quality'&&!c.synthetic&&[c.feedback_key,...(c._feedbackKeys||[])].some(key=>state.feedback.some(f=>f.feedback_key===key));}
function identityCell(c,field){const value=field==='tid'?c.tid:c.annotator;if(!editableIdentityCase(c))return esc(value);const pending=value==='待匹配',label=field==='tid'?'TID':'标注人';return `<button class="identity-edit${pending?' pending':''}" type="button" data-key="${esc(c.feedback_key)}" data-field="${field}" title="管理员修改${label}" aria-label="管理员修改${label}：${esc(value)}"><span>${esc(value)}</span></button>`;}
function personCell(c,field){if(field==='annotator')return identityCell(c,'annotator');const value=c.responsible_inspector;if(value!=='待匹配'||!state.feedback.some(f=>f.feedback_key===c.feedback_key))return esc(value);return `<button class="manual-match" data-key="${esc(c.feedback_key)}" data-field="inspector" title="手动填写原始质检人">待匹配 · 编辑</button>`;}
function bindManualMatches(root=document){root.querySelectorAll('.identity-edit').forEach(b=>b.onclick=()=>openIdentityEdit(b.dataset.key,b.dataset.field));root.querySelectorAll('.manual-match').forEach(b=>b.onclick=()=>updateManualMatch(b.dataset.key,b.dataset.field));}
async function updateManualMatch(key,field){const actor=await ensureActor();if(!actor)return;const f=state.feedback.find(x=>x.feedback_key===key);if(!f)return showStatus('未找到对应质检反馈记录。',true);const current=f.raw_row?.manualInspector,name=normalizeName(prompt('请输入原始质检人姓名',current||'')??'');if(!name)return;const related=state.feedback.filter(x=>x.tid===f.tid&&rowWorkstream(x)===state.workstream);let saved=0;for(const row of related){const raw={...(row.raw_row||{}),manualInspector:name,manualMatchUpdatedBy:actor,manualMatchUpdatedAt:new Date().toISOString()};const {data,error}=await db.from('r2v_quality_feedback').update({raw_row:raw}).eq('feedback_key',row.feedback_key).select('feedback_key,raw_row,updated_at');if(error)return showStatus(`手动匹配失败：${error.message}`,true);if(!data?.length)return showStatus('手动匹配未写入共享数据库，请刷新后重试。',true);Object.assign(row,data[0]);saved++;}await refreshDailySnapshotsAfterMutation(related.map(row=>row.feedback_date));showStatus(`${workstreamLabel()}：原始质检人已手动匹配为“${name}”，已同步保存该 TID 的 ${saved} 条反馈记录。`);}
async function openIdentityEdit(key,field){const actor=await ensureActor();if(!actor)return;const c=state.cases.find(x=>x.feedback_key===key);if(!editableIdentityCase(c))return showStatus('该行不是可修改的质检反馈 Case。',true);const keys=[...new Set(c._feedbackKeys?.length?c._feedbackKeys:[c.feedback_key])],rows=keys.map(k=>state.feedback.find(f=>f.feedback_key===k)).filter(Boolean);if(!rows.length)return showStatus('未找到对应质检反馈记录。',true);state.pendingIdentityEdit={case:c,field,keys,versions:Object.fromEntries(rows.map(row=>[row.feedback_key,row.updated_at||'']))};const label=field==='tid'?'TID':'标注人',value=field==='tid'?c.tid:c.annotator;$('identityEditTitle').textContent=`修改${label}`;$('identityEditValueLabel').firstChild.textContent=`新${label}`;$('identityEditValue').value=value==='待匹配'?'':value;$('identityEditPin').value='';$('identityEditContext').textContent=`${workstreamLabel()} · ${day(c.feedback_date)} · 当前${label}：${value}。保存时只更新此 Case 的身份字段，不会改动申诉、复盘或修改/提交状态。`;$('identityEditError').textContent='';$('identityEditError').classList.add('hidden');$('identityEditDialog').classList.remove('hidden');$('identityEditBackdrop').classList.remove('hidden');requestAnimationFrame(()=>{$('identityEditValue').focus();$('identityEditValue').select();});}
function closeIdentityEdit(){state.pendingIdentityEdit=null;$('identityEditDialog').classList.add('hidden');$('identityEditBackdrop').classList.add('hidden');$('identityEditForm').reset();$('identityEditError').classList.add('hidden');}
async function submitIdentityEdit(event){event.preventDefault();const edit=state.pendingIdentityEdit;if(!edit)return;const actor=await ensureActor();if(!actor)return;const value=edit.field==='annotator'?normalizeName($('identityEditValue').value):String($('identityEditValue').value||'').trim(),pin=$('identityEditPin').value,errorEl=$('identityEditError'),button=$('identityEditSubmit');if(!value){errorEl.textContent=`请输入新的${edit.field==='tid'?'TID':'标注人'}。`;errorEl.classList.remove('hidden');return;}if(!pin){errorEl.textContent='请输入管理员密码。';errorEl.classList.remove('hidden');return;}button.disabled=true;button.textContent='正在安全保存…';const dates=edit.keys.map(key=>state.feedback.find(row=>row.feedback_key===key)?.feedback_date).filter(Boolean);try{const {data,error}=await db.rpc('r2v_admin_correct_case_identity',{p_feedback_keys:edit.keys,p_field:edit.field,p_value:value,p_pin:pin,p_actor:actor,p_expected_tid:edit.case.tid,p_expected_versions:edit.versions,p_workstream:state.workstream});if(error)throw error;if(!data)throw new Error('云端未返回保存结果');closeIdentityEdit();await markDailyCacheDirty(dates);state.loadedSignature='';await loadAll({forceDetail:true});showStatus(`${workstreamLabel()}：${edit.field==='tid'?'TID':'标注人'}已安全修改为“${value}”，申诉与人工处理状态均已保留。`);}catch(error){errorEl.textContent=String(error?.message||error).replace(/^.*?:\s*/,'')||'保存失败，请刷新后重试。';errorEl.classList.remove('hidden');}finally{button.disabled=false;button.textContent='确认保存';}}
function caseFilterBase(){return state.cases.filter(c=>!c.invalid&&inPeriod(c.case_date||c.feedback_date)&&(c.kind==='acceptance'||['P0','P1','P2'].includes(c.severity)));}
function setCaseFilterOptions(id,items,allLabel='全部'){const el=$(id);if(!el)return;const current=el.value||'all',unique=[...new Map(items.filter(x=>x?.value).map(x=>[x.value,x])).values()].sort((a,b)=>a.label.localeCompare(b.label,'zh-CN'));el.innerHTML=`<option value="all">${esc(allLabel)}</option>${unique.map(x=>`<option value="${esc(x.value)}">${esc(x.label)}</option>`).join('')}`;el.value=unique.some(x=>x.value===current)?current:'all';}
function populateCaseFilters(){const rows=caseFilterBase();setCaseFilterOptions('caseDateFilter',rows.map(c=>({value:day(c.feedback_date),label:day(c.feedback_date)||'无日期'})),'全部日期');setCaseFilterOptions('caseSourceFilter',rows.map(c=>({value:c.kind,label:c.kind==='quality'?'质检':'验收'})),'全部来源');setCaseFilterOptions('caseAnnotatorFilter',rows.map(c=>({value:c.annotator,label:c.annotator||'待匹配'})),'全部标注人');setCaseFilterOptions('caseInspectorFilter',rows.map(c=>({value:c.responsible_inspector,label:c.responsible_inspector||'待匹配'})),'全部质检人');setCaseFilterOptions('caseSeverityFilter',rows.map(c=>({value:c.kind==='quality'?c.severity:'—',label:c.kind==='quality'?(c.severity||'待定级'):'—'})),'全部等级');setCaseFilterOptions('caseReturnedFilter',rows.map(c=>({value:qualityReturned(c),label:qualityReturned(c)})),'全部打回状态');setCaseFilterOptions('caseCategoryFilter',rows.map(c=>({value:c.issue_category||'—',label:c.issue_category||'—'})),'全部类别');setCaseFilterOptions('caseReviewFilter',rows.flatMap(c=>(reviewCategories(c).length?reviewCategories(c):['未选择']).map(value=>({value,label:value}))),'全部复盘类型');setCaseFilterOptions('caseStatusFilter',rows.map(c=>({value:caseStatus(c),label:caseStatus(c)})),'全部状态');}
function filteredCases(){const value=id=>$(id)?.value||'all',text=id=>($(id)?.value||'').trim().toLowerCase(),term=text('caseSearch'),tid=text('caseTidFilter'),detail=text('caseDetailFilter'),review=value('caseReviewFilter');let rows=caseFilterBase();const exact=[[value('caseDateFilter'),c=>day(c.feedback_date)],[value('caseSourceFilter'),c=>c.kind],[value('caseStatisticsTypeFilter'),c=>statisticsType(c)],[value('caseAnnotatorFilter'),c=>c.annotator],[value('caseInspectorFilter'),c=>c.responsible_inspector],[value('caseSeverityFilter'),c=>c.kind==='quality'?c.severity:'—'],[value('caseReturnedFilter'),c=>qualityReturned(c)],[value('caseCategoryFilter'),c=>c.issue_category||'—'],[value('caseStatusFilter'),c=>caseStatus(c)]];for(const [selected,getter] of exact)if(selected!=='all')rows=rows.filter(c=>getter(c)===selected);if(review!=='all')rows=rows.filter(c=>review==='未选择'?!reviewCategories(c).length:reviewCategories(c).includes(review));if(tid)rows=rows.filter(c=>String(c.tid||'').toLowerCase().includes(tid));if(detail)rows=rows.filter(c=>String(c.issue_detail||'').toLowerCase().includes(detail));if(term)rows=rows.filter(c=>[c.tid,c.annotator,c.responsible_inspector,c.issue_category,c.issue_detail,reviewCategory(c),caseStatus(c),statisticsType(c)].some(v=>String(v||'').toLowerCase().includes(term)));return rows.sort(feedbackOrder);}
function pageRows(rows,type){const key=type==='case'?'casePage':'appealPage',pages=Math.max(1,Math.ceil(rows.length/state.pageSize));state[key]=Math.min(Math.max(1,state[key]||1),pages);const start=(state[key]-1)*state.pageSize;return {rows:rows.slice(start,start+state.pageSize),page:state[key],pages,total:rows.length};}
