function ensureAppealColumnControls(){if($('appealColumnButton'))return;const exportButton=$('exportAppealsBtn');if(!exportButton)return;const wrap=document.createElement('div');wrap.className='appeal-column-control';wrap.innerHTML='<button id="appealColumnButton" class="button secondary small" type="button" aria-expanded="false">列设置</button><div id="appealColumnPanel" class="appeal-column-panel hidden"><div class="appeal-column-panel-head"><strong>显示或折叠列</strong><button id="appealColumnReset" class="text-button" type="button">恢复精简</button></div><div class="appeal-column-options"></div><div class="appeal-column-panel-foot"><button id="appealColumnsShowAll" class="text-button" type="button">全部显示</button><button id="appealColumnsHideDetail" class="text-button" type="button">一键精简</button></div></div>';exportButton.parentElement.insertBefore(wrap,exportButton);$('appealColumnButton').onclick=()=>{const panel=$('appealColumnPanel'),open=panel.classList.toggle('hidden')===false;$('appealColumnButton').setAttribute('aria-expanded',String(open));};$('appealColumnReset').onclick=$('appealColumnsHideDetail').onclick=()=>setAppealHiddenColumns(defaultHiddenAppealColumns);$('appealColumnsShowAll').onclick=()=>setAppealHiddenColumns(new Set());}
