function appealColumnFields(head){return [...head.children].map((th,index)=>{const label=th.textContent.trim();return ({'日期':'date','统计类型':'statistics','TID':'tid','标注人':'annotator','标注日期':'annotationDate','负责人':'owner','原始质检人':'inspector','等级':'severity','质检是否打回':'returned','准确率关联状态':'accuracy','质检意见':'issue','质检图片':'evidence','申诉理由':'reason','提交人':'submitter','状态':'status','质检裁决人':'decider','裁决说明':'decision','更新时间':'updated','标注是否修改/提交':'changed','错误Case复盘':'review'}[label]||(`action-${index}`));});}
function appealDetailMarkup(c){return `<div class="appeal-detail-grid"><div class="appeal-detail-item"><span>标注日期</span><strong>${esc(appealAnnotationDate(c))}</strong></div><div class="appeal-detail-item"><span>质检是否打回</span><strong>${esc(qualityReturned(c))}</strong></div><div class="appeal-detail-item"><span>准确率关联状态</span><strong>${esc(accuracyLinkStatus(c))}</strong></div><div class="appeal-detail-item"><span>提交人</span><strong>${esc(c.appeal?.submitted_by||'—')}</strong></div><div class="appeal-detail-item wide"><span>质检意见</span><p>${esc(c.issue_detail||'—')}</p></div><div class="appeal-detail-item evidence"><span>质检图片</span>${appealEvidenceCell(c)}</div><div class="appeal-detail-item wide"><span>申诉理由</span><p>${esc(c.appeal?.reason||'尚未提交')}</p></div><div class="appeal-detail-item"><span>质检裁决人</span><strong>${esc(c.appeal?.decided_by||'—')}</strong></div><div class="appeal-detail-item wide"><span>裁决说明</span><p>${esc(c.appeal?.decision_note||'—')}</p></div><div class="appeal-detail-item"><span>更新时间</span><strong>${esc(c.appeal?dateTime(c.appeal.updated_at):'—')}</strong></div></div>`;}
function enhanceAppealRowDetails(){ensureAppealDetailButton();ensureAppealColumnControls();const table=document.querySelector('.appeal-table'),head=table?.querySelector('.column-headings'),filters=table?.querySelector('.column-filters');if(!table||!head||!filters)return;table.classList.add('appeal-compact');const fields=appealColumnFields(head);[...head.children].forEach((cell,i)=>cell.dataset.appealField=fields[i]);[...filters.children].forEach((cell,i)=>cell.dataset.appealField=fields[i]);const cases=pageRows(filteredAppeals(),'appeal').rows,rows=[...$('appealsTable').children].filter(row=>!row.classList.contains('filter-empty')&&!row.classList.contains('appeal-detail-row'));rows.forEach((row,index)=>{const c=cases[index];if(!c)return;[...row.children].forEach((cell,i)=>cell.dataset.appealField=fields[i]);const key=appealDetailKey(c),expanded=expandedAppealDetails.has(key),actionCell=row.lastElementChild,toggle=document.createElement('button');toggle.type='button';toggle.className='text-button appeal-expand-toggle';toggle.dataset.key=key;toggle.textContent=expanded?'收起':'展开';toggle.setAttribute('aria-expanded',String(expanded));actionCell.insertBefore(toggle,actionCell.firstChild);const detail=document.createElement('tr');detail.className=`appeal-detail-row${expanded?'':' hidden'}`;detail.dataset.detailKey=key;detail.innerHTML=`<td colspan="${fields.filter(field=>!appealDetailFields.has(field)).length}">${appealDetailMarkup(c)}</td>`;row.insertAdjacentElement('afterend',detail);toggle.onclick=()=>{const open=!expandedAppealDetails.has(key);if(open)expandedAppealDetails.add(key);else expandedAppealDetails.delete(key);toggle.textContent=open?'收起':'展开';toggle.setAttribute('aria-expanded',String(open));detail.classList.toggle('hidden',!open);updateAppealDetailButton();};});document.querySelectorAll('#appealsTable .appeal-detail-row .appeal-evidence-button').forEach(button=>button.onclick=()=>openCase(button.dataset.key));applyAppealColumnVisibility();renderAppealColumnOptions();updateAppealDetailButton();}
function updateAppealDetailButton(){const button=$('toggleAllAppealDetails'),cases=filteredAppeals(),allExpanded=cases.length>0&&cases.every(c=>expandedAppealDetails.has(appealDetailKey(c)));if(!button)return;button.textContent=allExpanded?'全部收起':'全部展开';button.setAttribute('aria-expanded',String(allExpanded));}
function toggleAllAppealDetails(){const cases=filteredAppeals(),collapse=cases.length>0&&cases.every(c=>expandedAppealDetails.has(appealDetailKey(c)));cases.forEach(c=>{const key=appealDetailKey(c);if(collapse)expandedAppealDetails.delete(key);else expandedAppealDetails.add(key);});renderAppeals();}
function ensureStatisticsTypeColumn(tableSelector,filterId,afterIndex,renderFn){const table=document.querySelector(tableSelector),head=table?.querySelector('.column-headings'),filters=table?.querySelector('.column-filters');if(!head||!filters)return;if(!$(filterId)){head.children[afterIndex].insertAdjacentHTML('afterend','<th data-column="statistics-type">统计类型</th>');filters.children[afterIndex].insertAdjacentHTML('afterend',`<th data-column="statistics-type"><select id="${filterId}" aria-label="筛选统计类型"><option value="all">全部统计类型</option><option value="原生产">原生产</option><option value="新规正常生产">新规正常生产</option><option value="新SOP复检">新SOP复检</option></select></th>`);$(filterId).onchange=renderFn;}}
