const renderCasesCore=renderCases;
renderCases=function(){ensureStatisticsTypeColumn('.case-table','caseStatisticsTypeFilter',1,renderCases);renderCasesCore();injectStatisticsTypeCells('casesTable',pageRows(filteredCases(),'case').rows,2);};
renderAppeals=function(){ensureStatisticsTypeColumn('.appeal-table','appealStatisticsTypeFilter',0,renderAppeals);renderAppealsCore();injectStatisticsTypeCells('appealsTable',pageRows(filteredAppeals(),'appeal').rows,1);ensureAppealEvidenceStyles();enhanceAppealEvidenceColumn();enhanceAppealRowDetails();};
function resolveWorkbookPath(base,target){const parts=`${base}/${target}`.replace(/\\/g,'/').split('/'),out=[];for(const part of parts){if(!part||part==='.')continue;if(part==='..')out.pop();else out.push(part);}return out.join('/');}
function clearAppealFilters(){['appealDateFilter','appealStatisticsTypeFilter','appealAnnotatorFilter','appealAnnotationDateFilter','appealOwnerFilter','appealInspectorFilter','appealSeverityFilter','appealReturnedFilter','appealAccuracyFilter','appealSubmitterFilter','appealStatusFilter','appealDeciderFilter','appealUpdatedFilter','appealChangedFilter','appealReviewFilter'].forEach(id=>{if($(id))$(id).value='all'});['appealTidFilter','appealIssueFilter','appealReasonFilter','appealDecisionFilter'].forEach(id=>{if($(id))$(id).value=''});renderAppeals();}
function exportAppeals(){const rows=filteredAppeals();if(!rows.length)return showStatus('当前筛选条件下没有可导出的申诉记录。',true);const data=rows.map(c=>({'日期':appealCaseDate(c),'统计类型':statisticsType(c),'TID':c.tid,'标注人':c.annotator,'标注日期':appealAnnotationDate(c),'负责人':staffBoss(c.annotator)||'—','质检人':c.responsible_inspector,'错误等级':c.severity,'质检是否打回':qualityReturned(c),'准确率关联状态':accuracyLinkStatus(c),'质检意见':c.issue_detail||'','申诉理由':c.appeal?.reason||'','提交人':c.appeal?.submitted_by||'','申诉状态':appealDisplayStatus(c),'质检裁决人':c.appeal?.decided_by||'','裁决说明':c.appeal?.decision_note||'','更新时间':c.appeal?dateTime(c.appeal.updated_at):'','标注是否修改/提交':changedStatus(c),'错误Case复盘':reviewCategory(c)}));const ws=XLSX.utils.json_to_sheet(data),wb=XLSX.utils.book_new();ws['!cols']=[12,14,30,12,12,12,12,10,14,18,45,35,12,12,12,35,18,20,20].map(w=>({wch:w}));XLSX.utils.book_append_sheet(wb,ws,'申诉记录');XLSX.writeFile(wb,`R2V_申诉记录_${day(new Date())}.xlsx`);showStatus(`已按当前筛选与质检表顺序导出 ${rows.length} 条申诉记录。`);}
async function updateFeedbackTracking(el){const actor=await ensureActor();if(!actor)return renderAll();const f=state.feedback.find(x=>x.feedback_key===el.dataset.key);if(!f)return showStatus('未找到对应质检反馈记录。',true);const active=activeFeedbackRows().find(row=>row._feedbackKeys?.includes(f.feedback_key)),keys=[...new Set(active?._feedbackKeys||[f.feedback_key])],now=new Date().toISOString(),isChanged=el.dataset.field==='changed',values=isChanged?null:[...el.closest('.review-multiselect').querySelectorAll('input[type="checkbox"]:checked')].map(input=>input.value);el.classList.add('saving');let saved=0,dates=[];for(const key of keys){const row=state.feedback.find(x=>x.feedback_key===key);if(!row)continue;const raw={...(row.raw_row||{})},payload={};if(isChanged){payload.changed=el.value==='true';raw.changedManagedOnline=true;raw.trackingUpdatedBy=actor;raw.trackingUpdatedAt=now;}else{raw.reviewCategories=values;raw.reviewCategory=values.join('、');raw.reviewManagedOnline=true;raw.reviewUpdatedBy=actor;raw.reviewUpdatedAt=now;}payload.raw_row=raw;const {data,error}=await db.from('r2v_quality_feedback').update(payload).eq('feedback_key',key).select('feedback_key,changed,raw_row,updated_at');if(error||!data?.length){el.classList.remove('saving');showStatus(`保存失败：${error?.message||'未写入共享数据库'}，已保存 ${saved}/${keys.length} 条关联记录。`,true);return loadAll({forceDetail:true});}Object.assign(row,data[0]);dates.push(row.feedback_date);saved++;}el.classList.remove('saving');await refreshDailySnapshotsAfterMutation(dates);showStatus(isChanged?'标注修改/提交状态已同步给所有人。':`错误 Case 复盘已同步给所有人（关联 ${saved} 条记录）。`);}

function openCase(key){const c=state.cases.find(x=>x.feedback_key===key);if(!c)return;const events=sortedEvents(c.tid);const evidence=Array.isArray(c.evidence)?c.evidence:[];let action='';if(c.kind==='quality'&&!c.invalid&&['P0','P1'].includes(c.severity)){action=`<section class="drawer-section appeal-decision-section"><h3>申诉处理</h3>${c.appeal?`<div class="appeal-summary">${appealStatusBadge(c)}<p>${esc(c.appeal.reason)}</p></div>${c.appeal.status==='submitted'?`<form id="decisionForm" class="appeal-form"><label for="decisionNote">质检裁决意见 <span>判定失败时必填</span></label><textarea id="decisionNote" name="decisionNote" placeholder="说明同意或驳回申诉的规则依据、判定理由"></textarea><div class="appeal-actions"><button class="button small decision-success" type="button" data-decision="approved">判定成功</button><button class="button small decision-failure" type="button" data-decision="rejected">判定失败</button></div><p id="decisionError" class="field-error hidden">判定失败必须填写质检裁决意见。</p></form>`:`<div class="decision-readonly"><span>质检裁决意见</span><p>${esc(c.appeal.decision_note||'未填写')}</p></div>`}`:`<form id="appealForm" class="appeal-form"><textarea name="reason" required placeholder="填写申诉理由与规则依据"></textarea><button class="button primary" type="submit">提交共享申诉</button></form>`}</section>`;}
  const appealTrail=c.appeal?`<section class="drawer-section"><h3>申诉流水</h3><div class="timeline"><div class="timeline-row"><time>${esc(dateTime(c.appeal.created_at))}</time><strong>提交申诉</strong><span>${esc(c.appeal.submitted_by)}：${esc(c.appeal.reason)}</span></div>${c.appeal.status!=='submitted'?`<div class="timeline-row"><time>${esc(dateTime(c.appeal.updated_at))}</time><strong>${appealStatus(c.appeal.status)}</strong><span>${esc(c.appeal.decided_by||'未记录裁决人')}：${esc(c.appeal.decision_note||'未填写裁决说明')}</span></div>`:''}</div></section>`:'';
  $('drawerContent').innerHTML=`<p class="eyebrow">${c.kind==='quality'?'QUALITY CASE':'ACCEPTANCE CASE'}</p><h2>${esc(c.tid)}</h2><section class="drawer-section"><div class="detail-grid"><div><span>标注责任人</span>${esc(c.annotator)}</div><div><span>质检责任人</span>${esc(c.responsible_inspector)}</div><div><span>反馈日期</span>${esc(day(c.feedback_date))}</div><div><span>错误等级</span>${c.kind==='quality'?severityBadge(c.severity):'验收不通过'}</div><div><span>问题类别</span>${esc(c.issue_category||'—')}</div><div><span>最终计错</span>${c.final_error?'是':'否'}</div></div></section><section class="drawer-section"><h3>反馈意见</h3><p>${esc(c.issue_detail||'暂无')}</p></section>${evidence.length?`<section class="drawer-section"><h3>质检截图</h3><div class="evidence-grid">${evidence.map((u,index)=>`<a href="${esc(u)}" target="_blank" rel="noreferrer"><img src="${esc(u)}" alt="质检证据 ${index+1}" loading="lazy" decoding="async"></a>`).join('')}</div></section>`:''}${action}${appealTrail}<section class="drawer-section"><h3>完整流水</h3><div class="timeline">${events.map(e=>`<div class="timeline-row"><time>${esc(dateTime(e.event_time))}</time><strong>${esc(e.event_name)}</strong><span>${esc(normalizeName(e.operator_name)||e.reject_reason||'')}</span></div>`).join('')||'暂无匹配流水'}</div></section>`;
  $('caseDrawer').classList.add('open');$('caseDrawer').setAttribute('aria-hidden','false');$('drawerBackdrop').classList.remove('hidden');const form=$('appealForm');if(form)form.onsubmit=async e=>{e.preventDefault();await submitAppeal(c,form.reason.value)};document.querySelectorAll('[data-decision]').forEach(b=>b.onclick=()=>decideAppeal(c,b.dataset.decision,$('decisionNote')?.value||''));}
function closeDrawer(){$('caseDrawer').classList.remove('open');$('caseDrawer').setAttribute('aria-hidden','true');$('drawerBackdrop').classList.add('hidden');$('drawerContent').replaceChildren();}
async function submitAppeal(c,reason){const actor=await ensureActor();if(!actor)return;reason=String(reason||'').trim();if(!reason)return showStatus('请填写申诉理由。',true);const form=$('appealForm'),button=form?.querySelector('button[type="submit"]');if(button){button.disabled=true;button.textContent='正在保存到共享看板…';}const {data,error}=await db.from('r2v_quality_appeals').insert({feedback_key:c.feedback_key,tid:c.tid,reason,status:'submitted',submitted_by:actor}).select('id,feedback_key,tid,reason,status,submitted_by,created_at,updated_at').single();if(error||!data?.id){if(button){button.disabled=false;button.textContent='提交共享申诉';}showStatus(`申诉未保存：${error?.message||'云端未返回保存结果'}，填写内容已保留，请重试。`,true);return;}state.appeals.push(data);closeDrawer();await refreshDailySnapshotsAfterMutation([c.feedback_date||c.case_date]);showStatus(`申诉已共享保存（${data.tid}），其他人的看板将自动同步。`);}
async function decideAppeal(c,status,note=''){const actor=await ensureActor();if(!actor||!c.appeal)return;note=String(note||'').trim();const errorEl=$('decisionError'),noteEl=$('decisionNote');if(status==='rejected'&&!note){errorEl?.classList.remove('hidden');noteEl?.focus();return}errorEl?.classList.add('hidden');document.querySelectorAll('[data-decision]').forEach(b=>b.disabled=true);const {data,error}=await db.from('r2v_quality_appeals').update({status,decided_by:actor,decision_note:note}).eq('id',c.appeal.id).select('id,status,decision_note,updated_at');if(error||!data?.length){document.querySelectorAll('[data-decision]').forEach(b=>b.disabled=false);return showStatus(error?.message||'裁决未写入共享数据库。',true)}await markDailyCacheDirty([c.feedback_date||c.case_date]);closeDrawer();await loadAll({forceDetail:true});showStatus(status==='approved'?'申诉成功，相关准确率已自动重新计算。':'申诉失败，质检裁决意见已保存，错误继续计入准确率。');}

function renderSopSettings(){const s=state.sopSettings;if(!$('sopSettingsForm'))return;$('sopStartDate').value=s.startDate||'';$('sopQualityEnabled').checked=s.qualityEnabled!==false;$('sopAcceptanceEnabled').checked=s.acceptanceEnabled!==false;$('sopSettingsSummary').textContent=s.enabled?`已从 ${s.startDate} 启用；质检：${s.qualityEnabled?'是':'否'}，验收：${s.acceptanceEnabled?'是':'否'}。最后更新：${s.updatedBy||'—'} ${dateTime(s.updatedAt)}`:'当前未启用，全部按原生产统计。';}
async function saveSopSettings(enabled){const actor=await ensureActor();if(!actor)return;const pin=$('sopAdminPin').value,startDate=$('sopStartDate').value;if(!pin)return showStatus('请输入管理员密码。',true);if(enabled&&!startDate)return showStatus('请先选择新 SOP 启用日期。',true);const {data,error}=await db.rpc('r2v_admin_save_sop_settings',{p_pin:pin,p_actor:actor,p_enabled:enabled,p_start_date:enabled?startDate:null,p_quality_enabled:$('sopQualityEnabled').checked,p_acceptance_enabled:$('sopAcceptanceEnabled').checked});if(error||!data)return showStatus(`共享设置保存失败：${error?.message||'未写入云端'}`,true);state.adminAudit.push(data);$('sopAdminPin').value='';loadSopSettings();await db.from('r2v_quality_daily_cache').update({is_dirty:true}).in('workstream',['single','multi']);renderAll();showStatus(enabled?'新 SOP 统计设置已保存到共享数据库。':'新 SOP 统计已停用，历史设置记录仍保留。');}
function renderImports(){const imports=activeImports(),auditLabel=action=>({'delete_import':'删除上传记录','sop_settings_updated':'更新新 SOP 统计设置','change_pin':'修改管理员密码','edit_case_identity':'修改 Case TID/标注人','correct_case_identity':'修改 Case TID/标注人'}[action]||'管理员操作');renderSopSettings();$('importHistory').innerHTML=imports.length?imports.slice(0,30).map(i=>`<div class="history-row"><div><strong>${esc(String(i.file_name).replace(/^【多镜头】/,''))}</strong><small> · ${esc(i.file_type)}</small></div><span>${i.row_count} 行</span><span>${esc(i.actor)} · ${esc(dateTime(i.created_at))}</span><button class="text-button import-delete" type="button" disabled title="为保护人工状态和申诉记录，上传批次删除功能已暂停">删除已暂停</button></div>`).join(''):`<p class="empty-cell">暂无${workstreamLabel()}共享上传记录。</p>`;$('adminAudit').innerHTML=state.adminAudit.length?state.adminAudit.slice().sort((a,b)=>new Date(b.created_at)-new Date(a.created_at)).slice(0,20).map(a=>`<div class="history-row"><div><strong>${auditLabel(a.action)}</strong><small>${esc(a.file_name||'')}</small></div><span>${esc(a.actor)}</span><span>${esc(dateTime(a.created_at))}</span></div>`).join(''):'<p class="empty-cell">暂无管理员操作记录。</p>';}
function beginDelete(id){const item=state.imports.find(i=>i.id===id);if(!item)return;state.pendingDelete=item;$('adminPanel').classList.remove('hidden');$('deleteConfirm').classList.remove('hidden');$('deleteFileName').textContent=`准备删除：${item.file_name}`;$('deletePin').value='';$('deletePin').focus();}
