function uploadedChangedResult(value){const text=String(value??'').trim(),positive=new Set(['是','已修改','已提交','已完成','已修改/提交','TRUE','true','1']),negative=new Set(['否','未修改','未提交','待修改','待修改/提交','FALSE','false','0']);if(positive.has(text))return {explicit:true,value:true,text};if(negative.has(text))return {explicit:true,value:false,text};return {explicit:false,value:false,text};}
