function mergeRowsByKey(current,updates,key){const merged=new Map(current.map(row=>[row[key],row]));for(const row of updates)merged.set(row[key],row);return [...merged.values()];}
async function fetchChangedRows(table,since,order,key,max=5000){const rows=[];for(let from=0;from<max;from+=1000){let query=db.from(table).select('*').gt(order,since).order(order,{ascending:true}).order(key,{ascending:true}).range(from,Math.min(from+999,max-1));const {data,error}=await query;if(error)throw error;rows.push(...(data||[]));if(!data||data.length<1000)break;}return rows;}
async function syncSharedState(){if(!db||sharedSyncBusy||sharedSyncPaused())return;sharedSyncBusy=true;try{const remote=await fetchSharedVersions(),[feedbackChanged,appealChanged,importsChanged]=remote.map((version,index)=>version!==state.sharedVersions[index]);if($('periodSelect')?.value==='idle'){state.sharedVersions=remote;if(importsChanged)showStatus('云端已有新数据；选择日期后会按需加载。');return;}if(importsChanged){state.sharedVersions=remote;state.loadedSignature='';if(state.view==='imports')await loadImportsOnly();else showStatus('云端已有新上传文件，点击“刷新”或重新点“确定”后载入当前日期；页面不会自动全量重载。');return;}if(!feedbackChanged&&!appealChanged)return;const [feedbackUpdates,appealUpdates]=await Promise.all([feedbackChanged?fetchChangedRows('r2v_quality_feedback',state.sharedVersions[0],'updated_at','feedback_key'):[],appealChanged?fetchChangedRows('r2v_quality_appeals',state.sharedVersions[1],'updated_at','id'):[]]),currentTids=new Set([...state.events,...state.feedback].map(row=>row.tid).filter(Boolean)),relevantFeedback=feedbackUpdates.filter(row=>rowWorkstream(row)===state.workstream&&(dateInCurrentScope(row.feedback_date)||currentTids.has(row.tid))),currentFeedbackKeys=new Set([...state.feedback,...relevantFeedback].map(row=>row.feedback_key)),relevantAppeals=appealUpdates.filter(row=>currentFeedbackKeys.has(row.feedback_key));state.sharedVersions=remote;if(!relevantFeedback.length&&!relevantAppeals.length)return;if(state.summaryMode){await loadAll({forceDetail:true});await persistDailySnapshots();await loadDailyCache();return;}if(relevantFeedback.length)state.feedback=mergeRowsByKey(state.feedback,relevantFeedback,'feedback_key');if(relevantAppeals.length)state.appeals=mergeRowsByKey(state.appeals,relevantAppeals,'id');rebuild();renderAll();const save=()=>persistDailySnapshots();if('requestIdleCallback' in window)requestIdleCallback(save,{timeout:8000});else setTimeout(save,100);}catch(error){console.warn('共享状态同步失败',error);}finally{sharedSyncBusy=false;}}
$('refreshBtn').onclick=async()=>{state.loadedSignature='';await loadAll({forceDetail:true});};
setInterval(syncSharedState,30000);
window.addEventListener('focus',()=>setTimeout(syncSharedState,300));
$('exportAppealsBtn').onclick=exportAppeals;
$('exportCasesBtn').onclick=exportCases;
$('caseReviewFilter').onchange=renderCases;
syncPeriodDates();renderIdentity();setView('overview',state.workstream);
